(35611, 'Romans 4:3', 'Romans', 4, 3, 'ځکه چې د خدای په کلام کې لیکل شوي دي: «ابراهیم په خدای باندې ایمان راوړ او د هغه ایمان له امله خدای هغه عادل وګاڼه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_3.mp3', '', 1761754199, 1761754199),
(35612, 'Romans 4:4', 'Romans', 4, 4, 'څوک چې کار کوي نو مزدوري یې اخلي، خو دا مزدوري په سوغات کې نه حسابیږي، بلکې د هغه حق دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_4.mp3', '', 1761754199, 1761754199),
(35613, 'Romans 4:5', 'Romans', 4, 5, 'خو څوک چې په عمل تکیه نه کوي او په هغه خدای باندې ایمان راوړي چې ګناه کار خلک عادل جوړوي، نو د هغه ایمان په عدالت کې حسابیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_5.mp3', '', 1761754199, 1761754199),
(35614, 'Romans 4:6', 'Romans', 4, 6, 'همدارنګه داود د هغه نېکمرغه سړي په هکله چې خدای بې له دې چې د هغه عملونه په پام کې ونیسي، هغه عادل ګڼي، داسې وایي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_6.mp3', '', 1761754199, 1761754199),
(35615, 'Romans 4:7', 'Romans', 4, 7, 'بختور دی هغه څوک چې سرکښي یې بخښل شوې هغه څوک چې په ګناهونو یې اچول شوې پرده', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_7.mp3', '', 1761754199, 1761754199),
(35616, 'Romans 4:8', 'Romans', 4, 8, 'بختور دی هغه څوک چې یې څښتن نه ګڼي مجرم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_8.mp3', '', 1761754199, 1761754199),
(35617, 'Romans 4:9', 'Romans', 4, 9, 'ایا دا خوشبختي یوازې د هغو خلکو دپاره ده چې سنت شوي دي یا د ناسنتو دپاره هم ده؟ ځکه چې مونږ ته ویل شوي دي چې ابراهیم د خپل ایمان له امله عادل وګڼل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_9.mp3', '', 1761754199, 1761754199),
(35618, 'Romans 4:10', 'Romans', 4, 10, 'خو دا کار کله وشو؟ ایا د سنت کېدلو نه مخکې وشو یا وروسته له سنت کېدلو؟ په یقین سره چې د سنت کېدلو نه مخکې وشو، وروسته نه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_10.mp3', '', 1761754199, 1761754199),
(35619, 'Romans 4:11', 'Romans', 4, 11, 'د هغه سنت کېدل یوه نښه وه چې دا ثابته کړي چې مخکې له دې چې هغه سنت شي، خدای هغه د خپل ایمان په وسیله عادل وګاڼه. نو ابراهیم د هغو ټولو خلکو پلار دی چې په خدای باندې ایمان راوړي او عادل ګڼل کیږي، که هغوی سنت شوي هم نه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_11.mp3', '', 1761754199, 1761754199),
(35620, 'Romans 4:12', 'Romans', 4, 12, 'همدارنګه هغه د سنت شویو خلکو پلار هم دی، یوازې په دې خاطر نه چې هغوی سنت شوي دي، بلکې دا چې هغوی د هغه ایمان د مثال څخه پیروي کوي چې زمونږ نیکه ابراهیم د سنت کېدلو نه مخکې درلود. د خدای وعده د هغو ټولو دپاره چې ایمان راوړي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_12.mp3', '', 1761754199, 1761754199),
(35621, 'Romans 4:13', 'Romans', 4, 13, 'خدای د ابراهیم او د هغه د اولادې سره وعده وکړه چې هغوی به د ټولې نړۍ وارثان وي. دا وعده په دې خاطر نه وه چې ابراهیم په شریعت باندې عمل وکړ، بلکې د دې په خاطر وه چې هغه ایمان راوړ او د ایمان په وسیله عادل وګڼل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_13.mp3', '', 1761754199, 1761754199),
(35622, 'Romans 4:14', 'Romans', 4, 14, 'ځکه که چېرې د خدای وعدې هغو خلکو ته ورکړل شي چې د شریعت پیروي کوي، نو بیا ایمان هېڅ معنی نه لري او د خدای وعده بې‌ارزښته ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_14.mp3', '', 1761754199, 1761754199),
(35623, 'Romans 4:15', 'Romans', 4, 15, 'ځکه چې شریعت د خدای د غضب سبب کیږي، خو چېرته چې شریعت نشته، نو هلته د شریعت ماتول هم نشته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_15.mp3', '', 1761754199, 1761754199),
(35624, 'Romans 4:16', 'Romans', 4, 16, 'نو دا وعده په ایمان باندې ولاړه ده، ترڅو دا وعده د فضل په وسیله وي او د ابراهیم د ټولې اولادې دپاره اعتبار ولري، یوازې د هغو خلکو دپاره نه چې په شریعت باندې عمل کوي، بلکې د هغو خلکو دپاره هم چې د ابراهیم په شان ایمان لري، ځکه چې ابراهیم زمونږ د ټولو نیکه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_16.mp3', '', 1761754199, 1761754199),
(35625, 'Romans 4:17', 'Romans', 4, 17, 'لکه څنګه چې د خدای په کلام کې لیکل شوي دي: «ته مې د ډېرو قومونو پلار کړی یې.» نو ابراهیم د خدای په نظر کې زمونږ پلار دی چې هغه ورباندې ایمان درلود، یعنې هغه خدای چې مړي راژوندي کوي او د نشت څخه شته جوړوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_17.mp3', '', 1761754199, 1761754199),
(35626, 'Romans 4:18', 'Romans', 4, 18, 'ابراهیم ایمان راوړ او باور یې وکړ او حتی په ناامیدۍ کې یې هیله وساتله، نو له دې امله هغه د ډېرو قومونو پلار شو. لکه څنګه چې خدای هغه ته ویلي وو: «ستا نسل به بې‌شمېره زیات شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_18.mp3', '', 1761754199, 1761754199),
(35627, 'Romans 4:19', 'Romans', 4, 19, 'کله چې ابراهیم شاوخوا سل کلن ؤ، که څه هم هغه پوه شو چې بدن یې نژدې مړ دی او ښځه یې ساره هم نه شي کولای اولاد راوړي، خو ایمان یې کمزوری نه شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_19.mp3', '', 1761754199, 1761754199),
(35628, 'Romans 4:20', 'Romans', 4, 20, 'ابراهیم هېڅکله هم د خدای په وعده باندې شک ونه کړ، بلکې ایمان یې هغه ته قوت ورکاوه او د خدای ثنا یې ویله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_20.mp3', '', 1761754199, 1761754199),
(35629, 'Romans 4:21', 'Romans', 4, 21, 'ځکه چې هغه پوره یقین درلود چې خدای په دې قادر دی چې خپله وعده پوره کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_21.mp3', '', 1761754199, 1761754199),
(35630, 'Romans 4:22', 'Romans', 4, 22, 'نو له دې امله ابراهیم د ایمان په وسیله عادل وګڼل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_22.mp3', '', 1761754199, 1761754199),
(35631, 'Romans 4:23', 'Romans', 4, 23, 'دا خبره چې «هغه عادل وګڼل شو» یوازې د هغه په خاطر ونه لیکل شوه،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_23.mp3', '', 1761754199, 1761754199),
(35632, 'Romans 4:24', 'Romans', 4, 24, 'بلکې زمونږ دپاره هم ولیکل شوه چې عادل وګڼل شو او په هغه باندې ایمان ولرو چې زمونږ څښتن عیسی یې د مړو نه راژوندی کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_24.mp3', '', 1761754199, 1761754199),
(35633, 'Romans 4:25', 'Romans', 4, 25, 'هغه زمونږ د سرغړونو په خاطر مرګ ته وسپارل شو او بېرته راژوندی شو، ترڅو مونږ د خدای په حضور کې عادل وګڼل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans4_verse_25.mp3', '', 1761754199, 1761754199),
(35634, 'John 8:1', 'John', 8, 1, 'خو عیسی د زیتون غره ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_1.mp3', '', 1761754199, 1761754199),
(35635, 'John 8:2', 'John', 8, 2, 'بله ورځ سهار وختي هغه بېرته د خدای کور ته لاړ او ټول خلک ورته راټول شول. هغه کښېناست او هغوی ته یې تعلیم پیل کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_2.mp3', '', 1761754199, 1761754199),
(35636, 'John 8:3', 'John', 8, 3, 'په دې وخت کې د شریعت عالمانو او فریسیانو یوه ښځه چې د زنا په وخت کې یې نیولې وه هغه ته راوستله او د ټولو په مخکې یې ودروله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_3.mp3', '', 1761754199, 1761754199),
(35637, 'John 8:4', 'John', 8, 4, 'هغوی عیسی ته وویل: «استاذه، دا ښځه د زنا کولو په وخت کې نیول شوې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_4.mp3', '', 1761754199, 1761754199),
(35638, 'John 8:5', 'John', 8, 5, 'موسی په شریعت کې مونږ ته حکم کړی دی چې داسې ښځې باید سنګسارې شي. خو ته په دې هکله څه وایې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_5.mp3', '', 1761754199, 1761754199),
(35639, 'John 8:6', 'John', 8, 6, 'هغوی دا خبره د دې دپاره وکړه چې عیسی په دام کې راونیسي، ترڅو وکولای شي په هغه باندې تور ولګوي. خو هغه خپل سر ښکته واچاوه او په خپله ګوته یې په ځمکه باندې لیکل پیل کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_6.mp3', '', 1761754199, 1761754199),
(35640, 'John 8:7', 'John', 8, 7, 'کله چې هغوی په پرله پسې توګه د هغه نه سوالونه کول، نو عیسی خپل سر راپورته کړ او هغوی ته یې وویل: «په تاسو کې چې کوم چا هېڅکله هم ګناه نه وي کړې، نو هغه به لومړنی کس وي چې هغه په تیږه باندې ولي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_7.mp3', '', 1761754199, 1761754199),
(35641, 'John 8:8', 'John', 8, 8, 'عیسی یوځل بیا خپل سر ښکته واچاوه او په ځمکه باندې یې لیکل کول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_8.mp3', '', 1761754199, 1761754199),
(35642, 'John 8:9', 'John', 8, 9, 'کله چې هغوی دا خبره واورېدله نو زاړه خلک لومړي لاړل او بیا ځوانان ورپسې روان شول. عیسی د هغې ښځې سره چې هلته لا ولاړه وه یوازې پاتې شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_9.mp3', '', 1761754199, 1761754199),
(35643, 'John 8:10', 'John', 8, 10, 'عیسی خپل سر راپورته کړ او هغې ښځې ته یې وویل: «هغوی څه شول؟ هېچا ته محکومه نه کړې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_10.mp3', '', 1761754199, 1761754199),
(35644, 'John 8:11', 'John', 8, 11, 'هغې ځواب ورکړ: «هېچا هم نه، ښاغلیه.» عیسی وویل: «نو بیا زه هم تا نه محکوموم، ځه او بیا نوره ګناه مه کوه.»] عیسی د نړۍ دپاره رڼا ده', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_11.mp3', '', 1761754199, 1761754199),
(35645, 'John 8:12', 'John', 8, 12, 'عیسی یوځل بیا د خلکو سره خبرې وکړې او ویې ویل: «زه د نړۍ دپاره رڼا یم! څوک چې زما پیروي کوي، هغه به په تیاره کې نه ګرځي، بلکې د هغه سره به د ژوندون رڼا وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_12.mp3', '', 1761754199, 1761754199),
(35646, 'John 8:13', 'John', 8, 13, 'فریسیانو هغه ته وویل: «ته د خپل ځان په هکله شاهدي ورکوې، نو ستا شاهدي اعتبار نه لري.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_13.mp3', '', 1761754199, 1761754199),
(35647, 'John 8:14', 'John', 8, 14, 'عیسی په ځواب کې وویل: «حتی که زه د خپل ځان په هکله هم شاهدي ورکوم نو زما شاهدي اعتبار لري، ځکه زه پوهېږم چې د کوم ځای نه راغلی یم او چېرته به ځم. خو تاسو نه پوهېږئ چې زه د کوم ځای نه راغلی یم او چېرته ځم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_14.mp3', '', 1761754199, 1761754199),
(35648, 'John 8:15', 'John', 8, 15, 'تاسو د انسانانو د رسمونو او رواجونو له مخې قضاوت کوئ، خو زه د هېچا په هکله داسې قضاوت نه کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_15.mp3', '', 1761754199, 1761754199),
(35649, 'John 8:16', 'John', 8, 16, 'خو که زه قضاوت هم کوم نو هغه سم دی، ځکه چې دا کار زه یوازې نه کوم بلکې هغه پلار چې زه یې رالېږلی یم په دې کار کې زما سره دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_16.mp3', '', 1761754199, 1761754199),
(35650, 'John 8:17', 'John', 8, 17, 'ستاسو په شریعت کې لیکل شوي دي چې که چېرې دوه کسه د یوې موضوع په هکله شاهدي ورکړي، نو هغه اعتبار لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_17.mp3', '', 1761754199, 1761754199),
(35651, 'John 8:18', 'John', 8, 18, 'یو زه یم چې د خپل ځان په هکله شاهدي ورکوم او بل شاهد زما پلار دی چې زه یې رالېږلی یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_18.mp3', '', 1761754199, 1761754199),
(35652, 'John 8:19', 'John', 8, 19, 'بیا هغوی د هغه نه پوښتنه وکړه: «ستا پلار چېرته دی؟» عیسی ځواب ورکړ: «تاسو نه ما پېژنئ او نه زما پلار. که تاسو زه پېژندلی، نو زما پلار به مو هم پېژانده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_19.mp3', '', 1761754199, 1761754199),
(35653, 'John 8:20', 'John', 8, 20, 'عیسی دا خبرې هغه وخت وکړلې، کله چې هغه د خدای د کور په خزانه کې خلکو ته تعلیم ورکاوه. خو هېچا هم هغه ونه نیوه، ځکه چې د هغه وخت لا نه ؤ رارسېدلی. د خپل مرګ په هکله د عیسی خبرې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_20.mp3', '', 1761754199, 1761754199),
(35654, 'John 8:21', 'John', 8, 21, 'عیسی یوځل بیا هغوی ته وویل: «زه ځم او تاسو به ما پسې ګرځئ، خو که تاسو خپلو ګناهونو ته دوام ورکړئ نو مړه به شئ. چېرته چې زه ځم تاسو هلته نه شئ راتللی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_21.mp3', '', 1761754199, 1761754199),
(35655, 'John 8:22', 'John', 8, 22, 'نو خلکو وویل: «کله چې هغه وایي: ‹چېرته چې زه ځم تاسو هلته نه شئ راتللی،› ایا د هغه مقصد دا دی چې هغه به خپل ځان ووژني؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_22.mp3', '', 1761754199, 1761754199),
(35656, 'John 8:23', 'John', 8, 23, 'عیسی هغوی ته وویل: «تاسو د ځمکې خلک یئ خو زه د اسمان نه راغلی یم. تاسو د دې نړۍ یئ، خو زه د دې نړۍ نه یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john8_verse_23.mp3', '', 1761754199, 1761754199),
