(35704, 'Galatians 6:12', 'Galatians', 6, 12, 'کوم خلک چې تاسو په سنتولو مجبوروي، دا هغه خلک دي چې د نورو په مخکې خپل ځانونه داسې ښایي چې دوی ښه خلک دي. دوی نه غواړي چې د مسیح د صلیب په خاطر وځورول شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians6_verse_12.mp3', '', 1761754199, 1761754199),
(35705, 'Galatians 6:13', 'Galatians', 6, 13, 'ځکه حتی هغه خلک چې سنت شوي دي، هغوی په خپله په شریعت باندې عمل نه کوي، خو هغوی ستاسو سنتېدل د دې دپاره غواړي چې ستاسو په دې کار هغوی ویاړ وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians6_verse_13.mp3', '', 1761754199, 1761754199),
(35706, 'Galatians 6:14', 'Galatians', 6, 14, 'خو خدای دې نه کړي چې زه دې زمونږ د څښتن عیسی مسیح د صلیب څخه پرته په کوم بل شي باندې ویاړ وکړم. ځکه چې د هغه د صلیب په وسیله نړۍ زما دپاره مړه شوه او زه د نړۍ دپاره.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians6_verse_14.mp3', '', 1761754199, 1761754199),
(35707, 'Galatians 6:15', 'Galatians', 6, 15, 'نو سنتېدل یا نه سنتېدل کومه مهمه خبره نه ده، بلکې نوی پیدایښت مهم دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians6_verse_15.mp3', '', 1761754199, 1761754199),
(35708, 'Galatians 6:16', 'Galatians', 6, 16, 'سلامتي او رحم دې وي په هغه چا چې د دې قانون سره سم ژوند تېروي او هم د خدای په ټولو حقیقي اسراییلو باندې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians6_verse_16.mp3', '', 1761754199, 1761754199),
(35709, 'Galatians 6:17', 'Galatians', 6, 17, 'له دې نه وروسته دې هېڅوک ما نه په تکلیفوي، ځکه زما په بدن چې کوم داغونه دي د هغې نه معلومیږي چې زه د عیسی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians6_verse_17.mp3', '', 1761754199, 1761754199),
(35710, 'Galatians 6:18', 'Galatians', 6, 18, 'ای خویندو او ورونو! په تاسو ټولو باندې دې زمونږ د څښتن عیسی مسیح فضل وي. امین.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians6_verse_18.mp3', '', 1761754199, 1761754199);